import{_ as e,o as l,c as o,a5 as i}from"./chunks/framework.DJo0M80U.js";const h=JSON.parse('{"title":"MVC 和 MVVM 的区别","description":"MVC（Model View Controller）和 MVVM（Model View ViewModel）是两种常见的软件架构设计模式。它们的主要目的是分离关注点，提升代码的可维护性和可扩展性。尽管它们有相似的目标，但实现方式和侧重点有所不同。 MVC 模式 MVC 模式将应用。","frontmatter":{"title":"MVC 和 MVVM 的区别","date":"2026-08-11T00:00:00.000Z","categories":["Vue 系统教程"],"tags":["Vue","Vue3","前端","教程","OneNote","原理与手写实现"],"description":"MVC（Model View Controller）和 MVVM（Model View ViewModel）是两种常见的软件架构设计模式。它们的主要目的是分离关注点，提升代码的可维护性和可扩展性。尽管它们有相似的目标，但实现方式和侧重点有所不同。 MVC 模式 MVC 模式将应用。","sidebarWeight":11,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/f-vue/原理/MVC 和 MVVM 的区别.md"},"headers":[],"relativePath":"posts/Vue系统教程/05-原理与手写实现/MVC 和 MVVM 的区别.md","filePath":"posts/Vue系统教程/05-原理与手写实现/MVC 和 MVVM 的区别.md"}'),d={name:"posts/Vue系统教程/05-原理与手写实现/MVC 和 MVVM 的区别.md"};function a(r,t,n,s,V,M){return l(),o("div",null,[...t[0]||(t[0]=[i('<div><h1 id="mvc-和-mvvm-的区别" tabindex="-1">MVC 和 MVVM 的区别 <a class="header-anchor" href="#mvc-和-mvvm-的区别" aria-label="Permalink to &quot;MVC 和 MVVM 的区别&quot;">​</a></h1><blockquote><p>本节目标：理解“MVC 和 MVVM 的区别”的核心思路，并能把它用于实际开发或面试表达。 MVC（Model-View-Controller）和 MVVM（Model-View-ViewModel）是两种常见的软件架构设计模式。它们的主要目的是分离关注点，提升代码的可维护性和可扩展性。尽管它们有相似的目标，但实现方式和侧重点有所不同。</p></blockquote><p>MVC 模式 MVC 模式将应用程序分为三个部分：Model、View 和 Controller。</p><ol><li><strong>Model（模型）</strong>：</li></ol><ul><li>负责应用程序的数据和业务逻辑。</li><li>直接与数据库交互，处理数据的存取和验证。</li></ul><ol start="2"><li><strong>View（视图）</strong>：</li></ol><ul><li>负责显示数据，即用户界面部分。</li><li>从 Model 获取数据并展示给用户。</li></ul><ol start="3"><li><strong>Controller（控制器）</strong>：</li></ol><ul><li>负责处理用户输入和协调 Model 和 View 之间的交互。</li><li>接收用户的请求，调用 Model 处理数据，然后返回 View 显示结果。</li></ul><h5 id="工作原理" tabindex="-1">工作原理 <a class="header-anchor" href="#工作原理" aria-label="Permalink to &quot;工作原理&quot;">​</a></h5><ul><li>用户通过 View 进行交互。</li><li>Controller 接收用户的输入，调用 Model 处理业务逻辑。</li><li>Model 更新数据，Controller 将数据返回给 View，更新显示。</li></ul><h5 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h5><p>// Model class Model { constructor() { this.data = &#39;Hello, MVC!&#39;; } getData() { return this.data; } setData(data) { this.data = data; } } // View class View { constructor() { this.input = document.getElementById(&#39;input&#39;); this.button = document.getElementById(&#39;button&#39;); this.display = document.getElementById(&#39;display&#39;); } render(data) { this.display.innerText = data; } bindButton(handler) { this.button.addEventListener(&#39;click&#39;, handler); } } // Controller class Controller { constructor(model, view) { this.model = model; this.view = view; this.view.bindButton(this.handleButtonClick.bind(this)); this.view.render(this.model.getData()); } handleButtonClick() { const newData = this.view.input.value; this.model.setData(newData); this.view.render(this.model.getData()); } } // 使用 MVC 模式 const app = new Controller(new Model(), new View());</p><h4 id="mvvm-模式" tabindex="-1">MVVM 模式 <a class="header-anchor" href="#mvvm-模式" aria-label="Permalink to &quot;MVVM 模式&quot;">​</a></h4><p>MVVM 模式将应用程序分为三个部分：Model、View 和 ViewModel。</p><ol><li><strong>Model（模型）</strong>：</li></ol><ul><li>与 MVC 中的 Model 类似，负责数据和业务逻辑。</li></ul><ol start="2"><li><strong>View（视图）</strong>：</li></ol><ul><li>与 MVC 中的 View 类似，负责显示数据。</li></ul><ol start="3"><li><strong>ViewModel（视图模型）</strong>：</li></ol><ul><li>负责处理视图的显示逻辑和状态管理。</li><li>通过双向数据绑定（Two-Way Data Binding）将 Model 和 View 连接起来。</li></ul><h5 id="工作原理-1" tabindex="-1">工作原理 <a class="header-anchor" href="#工作原理-1" aria-label="Permalink to &quot;工作原理&quot;">​</a></h5><ul><li>View 和 ViewModel 之间存在双向数据绑定，ViewModel 负责同步 View 和 Model 的数据。</li><li>用户通过 View 进行交互，ViewModel 更新 Model，Model 的变化自动反映到 View 上。</li></ul><h5 id="示例-使用-vue-js" tabindex="-1">示例（使用 Vue.js） <a class="header-anchor" href="#示例-使用-vue-js" aria-label="Permalink to &quot;示例（使用 Vue.js）&quot;">​</a></h5><p>&lt;!DOCTYPE html&gt; &lt;html lang=&quot;en&quot;&gt; &lt;head&gt; &lt;meta charset=&quot;UTF-8&quot;&gt; &lt;title&gt;MVVM Example&lt;/title&gt; &lt;script src=&quot;<a href="https://cdn.jsdelivr.net/npm/vue@2" target="_blank" rel="noreferrer">https://cdn.jsdelivr.net/npm/vue@2</a>&quot;&gt;&lt;/script&gt; &lt;/head&gt; &lt;body&gt; &lt;div id=&quot;app&quot;&gt; &lt;p&gt;{{ message }}&lt;/p&gt; &lt;input v-model=&quot;message&quot; placeholder=&quot;Edit me&quot;&gt; &lt;/div&gt; &lt;script&gt; new Vue({ el: &#39;#app&#39;, data: { message: &#39;Hello, MVVM!&#39; } }); &lt;/script&gt; &lt;/body&gt; &lt;/html&gt;</p><p><strong>区别</strong></p><table tabindex="0"><thead><tr><th></th><th></th><th></th></tr></thead><tbody><tr><td><strong>特点</strong></td><td><strong>MVC</strong></td><td><strong>MVVM</strong></td></tr><tr><td>架构层次</td><td>Model-View-Controller</td><td>Model-View-ViewModel</td></tr><tr><td>数据绑定</td><td>手动数据绑定（单向）</td><td>双向数据绑定</td></tr><tr><td>视图更新</td><td>通过 Controller 手动更新</td><td>通过数据绑定自动更新</td></tr><tr><td>视图和数据交互</td><td>通过 Controller 进行协调</td><td>通过 ViewModel 直接进行数据绑定</td></tr><tr><td>复杂度</td><td>适用于简单或中等复杂度的应用</td><td>适用于复杂度较高的应用</td></tr><tr><td>控制器职责</td><td>处理用户输入，调用 Model 和 View</td><td>处理视图逻辑和状态管理，连接 View 和 Model</td></tr></tbody></table><p><strong>总结</strong> MVC 和 MVVM 都是用于分离关注点的设计模式，但它们在实现细节和使用场景上有所不同。MVC 更强调控制器的作用，适用于简单和中等复杂度的应用，而 MVVM 通过双向数据绑定简化了视图和模型的交互，适用于复杂的用户界面开发。选择哪种模式应根据具体的项目需求和开发团队的熟悉程度来决定。</p></div>',1)])])}const c=e(d,[["render",a]]);export{h as __pageData,c as default};
